-- Inert test-only receipt ledger. No dispatch route or RPC is enabled.
-- Generated by pinned Supabase CLI in isolated CI run 46122997607; guarded release only.
-- No API-facing RPCs or routes are exposed by this draft.
-- CRM email_messages cannot hold a provider ID until status='sent'.
-- Keep provider acceptance and signed events separately from Gmail IDs.
create table crm_private.resend_correspondence_attempts (
  email_message_id uuid primary key references public.email_messages(id) on delete restrict,
  outbox_id uuid not null unique references public.integration_outbox(id) on delete restrict,
  artist_id uuid not null check (artist_id = 'a1111111-1111-4111-8111-111111111111'::uuid),
  recipient text not null check (recipient = 'vvetrov41@gmail.com'), -- test-only phase
  payload_sha256 text not null check (payload_sha256 ~ '^[0-9a-f]{64}$'),
  prepared_at timestamptz not null default now(),
  state text not null default 'prepared' check (state in ('prepared','uncertain','accepted','rejected')),
  provider_message_id uuid unique,
  rfc_message_id text,
  accepted_at timestamptz,
  updated_at timestamptz not null default now(),
  check ((state = 'accepted') = (provider_message_id is not null)),
  check ((state = 'accepted') = (accepted_at is not null)),
  check (rfc_message_id is null or (provider_message_id is not null and
    length(rfc_message_id) <= 998 and rfc_message_id ~ '^<[^[:space:]<>]+>$'))
);
alter table crm_private.resend_correspondence_attempts enable row level security;
revoke all on crm_private.resend_correspondence_attempts from public, anon, authenticated, service_role;

-- Signed events may arrive before the API receipt is committed. Keep them
-- unmatched until an exact provider ID, sender and recipient can be bound.
-- Do not infer the job from subject, date, or recipient alone.
create table crm_private.resend_correspondence_events (
  event_id text primary key check (event_id ~ '^[A-Za-z0-9_-]{8,200}$'),
  provider_message_id uuid not null,
  event_type text not null check (event_type in ('email.sent','email.delivered','email.delivery_delayed','email.bounced','email.complained','email.failed','email.suppressed')),
  sender text not null check (sender = 'info@vishartattoo.com'),
  recipient text not null check (recipient = 'vvetrov41@gmail.com'),
  rfc_message_id text check (rfc_message_id is null or (length(rfc_message_id)<=998 and rfc_message_id ~ '^<[^[:space:]<>]+>$')),
  occurred_at timestamptz not null,
  received_at timestamptz not null default now(),
  matched_email_message_id uuid references crm_private.resend_correspondence_attempts(email_message_id) on delete restrict
);
create index resend_correspondence_events_provider_idx
 on crm_private.resend_correspondence_events(provider_message_id, occurred_at);
alter table crm_private.resend_correspondence_events enable row level security;
revoke all on crm_private.resend_correspondence_events from public, anon, authenticated, service_role;

-- This read-only view is private and not accessible to API roles. A terminal
-- negative receipt must not be silently overwritten by a late "sent" event.
-- Distinguish accepted from delivered; preserve the signed event history.
create view crm_private.resend_correspondence_delivery_state with (security_invoker=true) as
select a.email_message_id, a.outbox_id, a.artist_id, a.provider_message_id,
 a.state as acceptance_state,
 case
   when bool_or(e.event_type='email.complained') then 'complained'
   when bool_or(e.event_type='email.bounced') then 'bounced'
   when bool_or(e.event_type='email.suppressed') then 'suppressed'
   when bool_or(e.event_type='email.failed') then 'failed'
   when bool_or(e.event_type='email.delivered') then 'delivered'
   when bool_or(e.event_type='email.delivery_delayed') then 'delayed'
   when bool_or(e.event_type='email.sent') then 'sent'
   else a.state
 end as delivery_state
from crm_private.resend_correspondence_attempts a
left join crm_private.resend_correspondence_events e on
 e.matched_email_message_id=a.email_message_id and e.provider_message_id=a.provider_message_id
 and e.sender='info@vishartattoo.com' and e.recipient=a.recipient
group by a.email_message_id,a.outbox_id,a.artist_id,a.provider_message_id,a.state;
revoke all on crm_private.resend_correspondence_delivery_state from public, anon, authenticated, service_role;

-- REQUIRED BEFORE ROUTING:
-- 1. Atomic reservation in a backend-only RPC with active lease/artist/client/
--    approval/lifecycle validation using service_resolve_gmail_outbox_target.
--    Persist immutable hash and timestamp before provider network request.
-- 2. Modify legacy claim and acknowledgment paths atomically to exclude
--    reserved Resend rows; no stale legacy worker may send or ack them.
--    Guard against operator retries, lease recovery, cancellation and rollback.
-- 3. Receipt recording checks exact reservation, immutable payload and provider
--    ID; commit email_messages/provider and integration_outbox state in one txn.
-- 4. Event ingest verifies HMAC before DB; dedupe event_id with collision
--    detection; link only exact provider ID + recipient and pinned artist.
-- 5. Existing review and thread linkage must use actual RFC and Gmail IDs;
--    never write provider_message_id as a Gmail thread ID.
-- 6. No client traffic until test-only phase, ACL/manifest, pgTAP and guarded
--    release all pass. Revisit retention/deletion constraints before live.
